//! Id ordering and validation (D6).
//!
//! - [`byte_order`]: the Phase B comparator, plain `Ord for str` (byte order).
//! - [`is_valid_id`] / [`is_valid_client_action_id`]: the D6 id rules.
//! - [`compare`] (feature `ts-compat`): a model of ICU root collation over the
//!   id alphabet, sign-equal to the TS engine's `a.localeCompare(b)` (V8 + ICU,
//!   default locale). It uses a key table generated by
//!   `scripts/oracle/collation-table.ts` from Node's `Intl.Collator`. Gate:
//!   `cargo test -p race-core --features ts-compat --test collate` (1M pairs,
//!   100% sign-equal to Node).
//!
//! ICU facts the model relies on (verified exhaustively for every id of length
//! <= 3 and on 1M generated pairs, Node 24.17 / ICU 78.3):
//! - Every character in `[0-9A-Za-z_:-]` maps to exactly one collation
//!   element: no contractions, expansions or ignorables.
//! - Primary order is `_ < - < : < 0..9 < a/A < b/B < ... < z/Z`. Punctuation
//!   sorts before digits, and case is not a primary difference.
//! - There are no secondary differences in this alphabet.
//! - Case is a tertiary difference with lowercase first (`caseFirst: false`).
//! - The result is the same for `localeCompare` under `LANG` unset, `C`,
//!   `en_US.UTF-8` and `vi_VN.UTF-8` (V8 maps ICU's POSIX fallback to
//!   `en-US`), and for `Intl.Collator` with `undefined`, `'en'` and `'vi'`.

use core::cmp::Ordering;

/// Longest id allowed by D6.
pub const MAX_ID_LEN: usize = 64;
/// Shortest `clientActionId` allowed by D6.
pub const MIN_CLIENT_ACTION_ID_LEN: usize = 8;

/// Phase B id order: byte order, which equals UTF-16 code-unit order on the
/// ASCII id alphabet.
#[inline]
#[must_use]
pub fn byte_order(a: &str, b: &str) -> Ordering {
    a.cmp(b)
}

/// True if `byte` is in the id alphabet `[0-9A-Za-z_:-]`.
#[inline]
#[must_use]
pub const fn is_id_byte(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b':' | b'-')
}

/// D6 id rule: `^[0-9A-Za-z_:-]{1,64}$`. Applies to player ids, item keys,
/// pickup, hazard and track ids, and wild instance ids.
#[must_use]
pub fn is_valid_id(id: &str) -> bool {
    let bytes = id.as_bytes();
    (1..=MAX_ID_LEN).contains(&bytes.len()) && bytes.iter().all(|&byte| is_id_byte(byte))
}

/// D6 `clientActionId` rule: the id alphabet with 8 to 64 characters (a
/// lowercase UUID qualifies).
#[must_use]
pub fn is_valid_client_action_id(id: &str) -> bool {
    let bytes = id.as_bytes();
    (MIN_CLIENT_ACTION_ID_LEN..=MAX_ID_LEN).contains(&bytes.len())
        && bytes.iter().all(|&byte| is_id_byte(byte))
}

#[cfg(feature = "ts-compat")]
#[path = "collation_table.rs"]
mod table;

/// The id alphabet in ICU collation order, from the generated table.
#[cfg(feature = "ts-compat")]
pub const ICU_ORDER: &str = table::ORDER;

/// Primary weight. Bytes outside the id alphabet sort after every id byte, by
/// byte value. That order is deterministic but is NOT ICU's; validate ids
/// first (see [`is_valid_id`]).
#[cfg(feature = "ts-compat")]
#[inline]
fn primary(byte: u8) -> u16 {
    match table::PRIMARY.get(usize::from(byte)) {
        Some(&weight) if weight != 0 => u16::from(weight),
        _ => 0x100 + u16::from(byte),
    }
}

#[cfg(feature = "ts-compat")]
#[inline]
fn tertiary(byte: u8) -> u8 {
    table::TERTIARY.get(usize::from(byte)).copied().unwrap_or(0)
}

/// `a.localeCompare(b)` as the TS engine computes it, for ids in the D6
/// alphabet: a primary pass (the shorter string first when one is a primary
/// prefix of the other), then a tertiary (case) pass.
///
/// Returns `Equal` only for identical strings. Input outside the alphabet
/// gets a deterministic total order that does not model ICU (see `primary`).
#[cfg(feature = "ts-compat")]
#[must_use]
pub fn compare(a: &str, b: &str) -> Ordering {
    let (a, b) = (a.as_bytes(), b.as_bytes());
    for (&x, &y) in a.iter().zip(b) {
        let order = primary(x).cmp(&primary(y));
        if order != Ordering::Equal {
            return order;
        }
    }
    let order = a.len().cmp(&b.len());
    if order != Ordering::Equal {
        return order;
    }
    for (&x, &y) in a.iter().zip(b) {
        let order = tertiary(x).cmp(&tertiary(y));
        if order != Ordering::Equal {
            return order;
        }
    }
    // Equal keys on the alphabet imply equal bytes. Out-of-alphabet input
    // falls back to bytes so the order stays total.
    a.cmp(b)
}
